create or replace function public.confirm_utility_bill(p_utility_bill_id uuid,p_manual_allocations jsonb default null) returns public.utility_bills language plpgsql security definer set search_path='' as $$ declare b public.utility_bills; c public.property_utility_configs; rel record; n int; i int:=0; allocated numeric:=0; each_amount numeric; item jsonb; target uuid; target_amount numeric; ch public.charges; begin select * into b from public.utility_bills where id=p_utility_bill_id for update; if not found then raise exception 'UTILITY_BILL_NOT_FOUND'; end if; if public.can_manage_administration(b.administration_id) is not true then raise exception 'MANAGEMENT_ACCESS_REQUIRED'; end if; if b.status<>'DRAFT' then raise exception 'UTILITY_BILL_NOT_DRAFT'; end if; select * into c from public.property_utility_configs where id=b.utility_config_id; if c.distribution_method='MANUAL' then if p_manual_allocations is null or jsonb_typeof(p_manual_allocations)<>'array' then raise exception 'MANUAL_ALLOCATIONS_REQUIRED'; end if; for item in select value from jsonb_array_elements(p_manual_allocations) loop target:=(item->>'rental_relationship_id')::uuid; target_amount:=(item->>'amount')::numeric; if target_amount<0 then raise exception 'INVALID_ALLOCATION_AMOUNT'; end if; if not exists(select 1 from public.rental_relationships r join public.rental_relationship_subjects rs on rs.rental_relationship_id=r.id join public.rental_subjects s on s.id=rs.rental_subject_id join public.rooms rm on rm.id=s.room_id where r.id=target and r.administration_id=b.administration_id and r.status in('ACTIVE','ENDING') and rm.property_id=b.property_id) then raise exception 'RELATIONSHIP_NOT_ACTIVE_IN_PROPERTY'; end if; insert into public.utility_allocations(administration_id,utility_bill_id,rental_relationship_id,amount) values(b.administration_id,b.id,target,target_amount); allocated:=allocated+target_amount; end loop; if allocated<>b.amount then raise exception 'ALLOCATIONS_MUST_EQUAL_BILL'; end if; else select count(distinct r.id) into n from public.rental_relationships r join public.rental_relationship_subjects rs on rs.rental_relationship_id=r.id join public.rental_subjects s on s.id=rs.rental_subject_id join public.rooms rm on rm.id=s.room_id where r.administration_id=b.administration_id and r.status in('ACTIVE','ENDING') and rm.property_id=b.property_id; if n=0 then raise exception 'NO_ACTIVE_ROOM_RENTALS'; end if; each_amount:=round(b.amount/n,2); for rel in select distinct r.id from public.rental_relationships r join public.rental_relationship_subjects rs on rs.rental_relationship_id=r.id join public.rental_subjects s on s.id=rs.rental_subject_id join public.rooms rm on rm.id=s.room_id where r.administration_id=b.administration_id and r.status in('ACTIVE','ENDING') and rm.property_id=b.property_id order by r.id loop i:=i+1; target_amount:=case when i=n then b.amount-allocated else each_amount end; insert into public.utility_allocations(administration_id,utility_bill_id,rental_relationship_id,amount) values(b.administration_id,b.id,rel.id,target_amount); allocated:=allocated+target_amount; end loop; end if; for rel in select * from public.utility_allocations where utility_bill_id=b.id loop insert into public.charges(administration_id,rental_relationship_id,charge_type,origin,description,period_start,period_end,due_date,amount,currency,source_type,source_id) values(b.administration_id,rel.rental_relationship_id,'UTILITY','UTILITY_ALLOCATION','Servicio público '||c.utility_code,b.period_start,b.period_end,coalesce(b.due_date,b.period_end),rel.amount,'COP','UTILITY_ALLOCATION',rel.id) returning * into ch; update public.utility_allocations set charge_id=ch.id where id=rel.id; end loop; update public.utility_bills set status='CHARGED',confirmed_at=now() where id=b.id returning * into b; return b; end $$;